import { afterAll, beforeAll, describe, expect, it, vi } from 'vitest';
import type { Pool } from 'pg';

// Replace only the query transport. Every notification repository query is
// still generated by the actual production repository under test.
vi.mock('@/infrastructure/database/queries', async () => {
  const { Pool } = await import('pg');
  const pool = new Pool({
    host: process.env.PGHOST || '127.0.0.1',
    port: Number(process.env.PGPORT || '5432'),
    database: process.env.PGDATABASE || 'ivts_test_notifications',
    user: process.env.PGUSER || 'ivts_test',
    password: process.env.PGPASSWORD || 'ivts_test_password',
  });
  return {
    __testPool: pool,
    findMany: async (sql: string, args?: unknown[]) => (await pool.query(sql, args)).rows,
    findOne: async (sql: string, args?: unknown[]) => (await pool.query(sql, args)).rows[0] ?? null,
    executeQuery: async (sql: string, args?: unknown[]) => (await pool.query(sql, args)).rowCount ?? 0,
  };
});

import * as queries from '@/infrastructure/database/queries';
import {
  findNotificationPage,
  getNotificationCounts,
  getNotificationStats,
  hideNotification,
  markAllNotificationsRead,
  markNotificationRead,
} from './notification.repository';

const integration = process.env.IVTS_PG_INTEGRATION === '1' ? describe : describe.skip;
const pool = (queries as unknown as { __testPool: Pool }).__testPool;
const viewer = { userId: 101, role: 'viewer', deviceAccessMode: 'assigned' };
const admin = { userId: 102, role: 'admin', deviceAccessMode: 'all' };

integration('real PostgreSQL notification visibility and mutations', () => {
  beforeAll(async () => {
    // No schema creation or data writes outside an isolated test database.
    if (!process.env.PGDATABASE?.startsWith('ivts_test_')) {
      throw new Error('Refusing notification integration test outside ivts_test_* database');
    }
    await pool.query(`CREATE TABLE devices (
      device_id text PRIMARY KEY, device_name text, vehicle_id text
    )`);
    await pool.query(`CREATE TABLE vehicles (
      id serial PRIMARY KEY, vehicle_id text UNIQUE NOT NULL,
      plate_number text, device_id text, updated_at timestamptz DEFAULT NOW()
    )`);
    await pool.query(`CREATE TABLE alerts (
      id bigint PRIMARY KEY, vehicle_id text, device_id text,
      alert_type text NOT NULL, title text NOT NULL, message text,
      created_at timestamptz DEFAULT NOW()
    )`);
    await pool.query(`CREATE TABLE user_device_access (user_id integer, device_id text)`);
    await pool.query(`CREATE TABLE notification_states (
      user_id integer, alert_id bigint, is_read boolean DEFAULT FALSE,
      read_at timestamptz, hidden_at timestamptz, updated_at timestamptz,
      PRIMARY KEY (user_id, alert_id)
    )`);
    await pool.query(`INSERT INTO devices (device_id, device_name) VALUES ('D1','Tracker 1'),('D2','Tracker 2')`);
    await pool.query(`INSERT INTO vehicles (vehicle_id, plate_number, device_id)
      VALUES ('V1','PLATE-ONE','D1'),('V2','PLATE-TWO','D2')`);
    await pool.query(`INSERT INTO alerts (id, device_id, vehicle_id, alert_type, title)
      VALUES (1,'D1',NULL,'motion','D1 motion'),(2,'D2',NULL,'motion','D2 motion'),
             (3,NULL,'V1','geofence','V1 geofence'),(4,NULL,NULL,'system','global')`);
    await pool.query(`INSERT INTO user_device_access (user_id,device_id) VALUES (101,'D1')`);
  });

  afterAll(async () => {
    await pool.end();
  });

  it('list, search, totals and category stats exclude all unassigned alerts', async () => {
    const rows = await findNotificationPage(viewer, {}, 20, 0);
    expect(rows.map((x) => Number(x.id)).sort()).toEqual([1, 3]);
    expect(await getNotificationCounts(viewer, {})).toEqual({ total: 2, unreadCount: 2 });
    const stats = await getNotificationStats(viewer);
    expect(stats.total).toBe(2);
    expect(stats.unreadCount).toBe(2);
    expect(stats.byType.zone).toBe(1);
    expect(stats.byType.alert).toBe(1);

    const search = await findNotificationPage(viewer, { search: 'D2' }, 10, 0);
    expect(search).toHaveLength(0);
    const paged = await findNotificationPage(viewer, {}, 1, 1);
    expect(paged).toHaveLength(1);
  });

  it('read, hide and mark-all cannot modify another device alert', async () => {
    await markNotificationRead(viewer, 2);
    await hideNotification(viewer, 2);
    expect((await pool.query('SELECT * FROM notification_states WHERE user_id = 101 AND alert_id = 2')).rowCount).toBe(0);
    await markAllNotificationsRead(viewer);
    const states = await pool.query('SELECT alert_id FROM notification_states WHERE user_id = 101 ORDER BY alert_id');
    expect(states.rows.map((x) => Number(x.alert_id))).toEqual([1, 3]);
    expect(await getNotificationCounts(viewer, { isRead: false })).toEqual({ total: 0, unreadCount: 0 });
  });

  it('revocation is immediate and all-access users retain visibility', async () => {
    await pool.query(`DELETE FROM user_device_access WHERE user_id = 101`);
    expect(await findNotificationPage(viewer, {}, 20, 0)).toHaveLength(0);
    expect((await getNotificationStats(viewer)).total).toBe(0);
    await pool.query(`INSERT INTO user_device_access (user_id,device_id) VALUES (101,'D2')`);
    expect((await findNotificationPage(viewer, {}, 20, 0)).map((x) => Number(x.id))).toEqual([2]);
    expect((await findNotificationPage(admin, {}, 20, 0)).length).toBe(4);
    expect((await getNotificationStats(admin)).total).toBe(4);
  });
});
